// Deployed copies are generated by tools/sync-cloud-auth.js.
const COLLECTIONS = ['MissionList', 'MarketList', 'StorageList', 'UserList'];
const WRITABLE = ['MissionList', 'MarketList', 'StorageList'];
function check(condition, message) { if (!condition) throw new Error(message); }
async function member(cloud) {
  const openid = cloud.getWXContext().OPENID;
  check(typeof openid === 'string' && openid.length > 0, 'UNAUTHENTICATED');
  const db = cloud.database();
  const users = await db.collection('UserList').where({_openid: openid}).limit(1).get();
  check(users.data && users.data.length === 1, 'FORBIDDEN');
  return {openid, db};
}
function collection(db, name, writable = false) {
  check((writable ? WRITABLE : COLLECTIONS).includes(name), 'INVALID_COLLECTION');
  return db.collection(name);
}
async function record(db, name, id) {
  check(typeof id === 'string' && id.length > 0 && id.length <= 128, 'INVALID_ID');
  const result = await collection(db, name).where({_id: id}).limit(1).get();
  check(result.data && result.data.length === 1, 'NOT_FOUND');
  return result.data[0];
}
function owned(item, openid) { check(item._openid === openid, 'FORBIDDEN_OWNER'); }
function credit(value, signed = false) {
  const number = Number(value);
  check(Number.isInteger(number) && Math.abs(number) <= 500 && (signed || number >= 0), 'INVALID_CREDIT');
  return number;
}
function boolean(value) { check(typeof value === 'boolean', 'INVALID_BOOLEAN'); return value; }
module.exports = {check, member, collection, record, owned, credit, boolean};
